/* Original scientific SVG illustrations; all coordinates are schematic, not measured data. */
function lessonVisual(s){if(typeof detailVisual==='function'){const v=detailVisual(s);if(v)return v}if(typeof reactivityVisual==='function'){const v=reactivityVisual(s);if(v)return v}if(s.legacy)return drawDiagram(s.visual.kind);const topic=s.id.split('.').slice(0,2).join('.');let z='';const title=t=>tx(360,25,t,16),foot=t=>tx(360,235,t,12);switch(topic){
case'S2.3':z=title('Metallic bonding: ions in a sea of mobile electrons')+Array.from({length:15},(_,i)=>atom(160+(i%5)*100,75+Math.floor(i/5)*56,'M⁺','#dce9f2',20)).join('')+Array.from({length:20},(_,i)=>marker(120+(i*73)%475,59+(i*43)%135,'#56a28a',3)).join('')+foot('Non-directional attraction binds the lattice; electrons can carry charge.');break;
case'S2.4':z=title('From bonding models to the properties of real materials')+line(360,54,146,205,'#aac8d2',3)+line(146,205,575,205,'#aac8d2',3)+line(575,205,360,54,'#aac8d2',3)+tx(360,45,'Ionic',14)+tx(120,218,'Metallic',14)+tx(603,218,'Covalent',14)+cir(360,154,18,'#e5cbaa','#d6af79')+tx(360,184,'mixed character',12);break;
case'S3.1':z=title('Periodic trends: effective nuclear attraction and distance')+rect(123,58,465,139,'#fff')+Array.from({length:40},(_,i)=>rect(142+(i%10)*43,75+Math.floor(i/10)*28,35,20,i%10>6?'#e0efdf':'#e5f0f8','#d4e3e8',3)).join('')+arrow(170,216,560,216,'#309b7b')+tx(360,240,'General increase in electronegativity across a period →',12)+tx(650,122,'↑ smaller',12)+tx(650,144,'radius',12);break;
case'S3.2':z=title('Organic classification depends on functional groups')+dpill(30,65,206,'Alcohol: R–OH')+dpill(258,65,206,'Aldehyde: R–CHO')+dpill(486,65,206,'Ketone: R–CO–R′')+dpill(30,122,206,'Carboxyl: R–COOH')+dpill(258,122,206,'Ester: R–COO–R′')+dpill(486,122,206,'Amine: R–NH₂')+foot('R represents an organic group. Functional groups guide properties and reactions.');break;
case'R1.1':z=title('Calorimetry: measure ΔT to estimate transferred heat')+`<path d="M150 69 L150 197 L325 197 L325 69" fill="#dcecf1" stroke="#91b4c3" stroke-width="3"/><rect x="155" y="130" width="165" height="61" fill="#abdbeb"/><rect x="145" y="64" width="185" height="9" fill="#c3d5d9"/><rect x="248" y="39" width="8" height="123" rx="4" fill="#db997e"/>`+tx(480,101,'q = mcΔT',25,'#267e72')+tx(480,145,'ΔH ≈ −q / n',20)+foot('The sign for the reaction is opposite to the heat change of the surroundings.');break;
case'R1.2':z=title('Hess’s law: different paths, the same total enthalpy change')+dpill(80,62,190,'Reactants')+dpill(454,62,190,'Products')+dpill(267,170,190,'Intermediate')+arrow(285,75,439,75)+line(175,101,348,165,'#709eab',3)+line(377,166,548,100,'#709eab',3)+tx(360,59,'ΔH direct',14)+tx(196,152,'ΔH₁',14)+tx(519,153,'ΔH₂',14)+foot('ΔH direct = ΔH₁ + ΔH₂, with signs adjusted for reaction direction.');break;
case'R1.3':z=title('Combustion and fuel cells: chemical energy becomes useful energy')+dpill(50,74,180,'Fuel + oxygen')+arrow(245,88,340,88)+dpill(355,74,310,'Oxidation products + energy')+rect(106,139,507,61,'#fff')+tx(360,165,'Complete hydrocarbon combustion → CO₂ + H₂O',16)+tx(360,187,'Incomplete combustion can form CO or carbon.',12);break;
case'R1.4':z=title('Spontaneity is determined by the sign of ΔG')+rect(113,65,497,132,'#fff')+tx(360,103,'ΔG = ΔH − TΔS',27,'#2b8273')+dpill(139,132,198,'ΔG < 0 : spontaneous')+dpill(367,132,218,'ΔG > 0 : non-spontaneous')+foot('Use compatible energy units and temperature in kelvin.');break;
case'R2.1':z=title('Reaction amounts follow balanced mole ratios')+dpill(39,73,175,'2H₂')+tx(246,93,'+',25)+dpill(282,73,144,'O₂')+arrow(449,87,511,87)+dpill(535,73,150,'2H₂O')+tx(360,157,'Mole ratio = 2 : 1 : 2',22,'#338c7c')+foot('A limiting reactant sets the maximum theoretical product yield.');break;
case'R2.2':z=title('A catalyst provides a pathway with lower activation energy')+line(83,208,643,208)+line(83,208,83,45)+tx(76,35,'Energy',12)+`<path d="M100 167 C180 167 231 30 325 43 S455 193 624 193" fill="none" stroke="#d39b78" stroke-width="4"/><path d="M100 167 C200 167 239 93 325 100 S455 193 624 193" fill="none" stroke="#4eab91" stroke-width="4"/>`+tx(362,229,'Reaction progress',12)+tx(523,62,'Uncatalysed',12,'#bd8969')+tx(523,86,'Catalysed',12,'#418e76');break;
case'R2.3':z=title('Dynamic equilibrium: equal forward and reverse rates')+rect(75,58,570,141,'#fff')+tx(183,120,'Reactants',19)+tx(536,120,'Products',19)+arrow(271,99,442,99)+`<path d="M442 136 L271 136 L282 129 M271 136 L282 143" fill="none" stroke="#69ad98" stroke-width="3"/>`+tx(360,175,'rate forward = rate reverse',16,'#3c8b77')+foot('Concentrations stay constant; they are not necessarily equal.');break;
case'R3.1':z=title('Brønsted–Lowry acids donate H⁺; bases accept H⁺')+dpill(38,72,146,'HA')+tx(217,93,'+',23)+dpill(253,72,146,'H₂O')+tx(439,94,'⇌',28)+dpill(479,72,104,'A⁻')+tx(611,93,'+',23)+dpill(645,72,62,'H₃O⁺')+line(117,119,530,119,'#78aa9e',2,'6 5')+tx(323,154,'HA and A⁻ are a conjugate acid–base pair.',15)+foot('Each conjugate pair differs by exactly one proton.');break;
case'R3.2':z=title('Redox: oxidation supplies electrons; reduction accepts them')+dpill(58,73,234,'Zn → Zn²⁺ + 2e⁻')+dpill(428,73,234,'Cu²⁺ + 2e⁻ → Cu')+arrow(298,85,422,85)+tx(360,64,'electrons',12)+tx(176,140,'Oxidation',18,'#bc8e6e')+tx(545,140,'Reduction',18,'#408e77')+foot('Oxidation occurs at the anode; reduction occurs at the cathode.');break;
case'R3.3':z=title('Radical substitution: chain initiation, propagation, termination')+dpill(43,63,186,'Initiation: Cl₂ → 2Cl•')+dpill(259,63,196,'Propagation: chain continues')+dpill(481,63,194,'Termination: radicals combine')+tx(360,141,'Cl• + CH₄ → HCl + CH₃•',19)+tx(360,178,'CH₃• + Cl₂ → CH₃Cl + Cl•',19)+foot('The propagation steps regenerate a radical, sustaining the chain.');break;
case'R3.4':z=title('Electron-pair sharing: donor → electron-deficient centre')+dpill(56,77,190,'Nucleophile / Lewis base')+dpill(434,77,231,'Electrophile / Lewis acid')+arrow(261,91,416,91,'#2b997b')+tx(360,149,'electron-pair donation',17,'#4c8877')+tx(360,186,'Curly arrows begin at the electron pair source.',15)+foot('A curly arrow tracks a PAIR of electrons; a fishhook tracks ONE electron.');break;
default:z=title(s.title)+rect(50,60,620,145,'#fff')+tx(360,127,s.summary.slice(0,70),14);
}return svg(z);}
